                        >{c('Subscription reminder').t`Cancel subscription`}</Button>
                    </div>
                </div>
            </div>
            {cancelRenderModal && (
                <CancelConfirmationModal
                    {...cancelModalProps}
                    ctaText={ctaText}
                    cancelSubscription={async () => {
                        await handleCancelSubscription();
                    }}
                    upsellPlan={config.upsellPlan}
