export function subscriptionExpires(): FreeSubscriptionResult;
export function subscriptionExpires(subscription: undefined | null, isCancellation?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: FreeSubscription, isCancellation?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel | undefined, isCancellation?: boolean): SubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel, isCancellation?: boolean): SubscriptionResult;
export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null,
    isCancellation = false
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    const activeTermOnly = isCancellation || subscription.Renew === Renew.Disabled;
    const latestSubscription = activeTermOnly ? subscription : (subscription.UpcomingSubscription ?? subscription);
    const renewDisabled = activeTermOnly || latestSubscription.Renew === Renew.Disabled;
    const renewEnabled = !activeTermOnly && latestSubscription.Renew === Renew.Enabled;
    const subscriptionExpiresSoon = renewDisabled;

    const planName = latestSubscription.Plans?.[0]?.Title;

    if (subscriptionExpiresSoon) {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: latestSubscription.PeriodEnd,
        };
    } else {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: null,
        };
    }
}

